mapper.select:
select c.* from integration_connections c
where c.tenant_id=#{tenantId}
  and #{scope.denyAll}=false
  and (
    #{scope.tenantWide}=true
    or c.connection_id in #{id}
    or c.owner_department_id in #{id}
    or exists(select 1 from org_department_closure dc where dc.tenant_id=c.tenant_id and dc.descendant_department_id=c.owner_department_id and dc.ancestor_department_id in #{id})
    or c.owner_group_id in #{id}
  )
  and c.connection_id not in #{id}
  and (c.owner_department_id is null or c.owner_department_id not in #{id})
  and not exists(select 1 from org_department_closure dd where dd.tenant_id=c.tenant_id and dd.descendant_department_id=c.owner_department_id and dd.ancestor_department_id in #{id})
  and (c.owner_group_id is null or c.owner_group_id not in #{id})
  and not exists(select 1 from resource_scope_denies d where d.tenant_id=c.tenant_id and d.resource_type='ISSUE_CONNECTION' and d.deny_state='ACTIVE' and d.valid_from<=now() and (d.valid_to is null or d.valid_to>now()) and d.principal_type=#{scope.principalType} and d.principal_id=#{scope.principalId} and (d.permission_code is null or d.permission_code=#{scope.permissionCode}) and (d.scope_type='TENANT' or (d.scope_type='RESOURCE' and d.scope_ref_id=c.connection_id) or (d.scope_type in ('OWNER','DEPARTMENT') and d.scope_ref_id=c.owner_department_id) or (d.scope_type='GROUP' and d.scope_ref_id=c.owner_group_id) or (d.scope_type='DEPARTMENT_SUBTREE' and exists(select 1 from org_department_closure x where x.tenant_id=c.tenant_id and x.ancestor_department_id=d.scope_ref_id and x.descendant_department_id=c.owner_department_id))))
order by c.connection_name,c.connection_id limit #{limit}

select p.* from integration_principals p
where p.tenant_id=#{tenantId} and p.connection_id=#{connectionId}
  and #{scope.denyAll}=false and (#{scope.tenantWide}=true
    or p.principal_id in #{id}
    or p.owner_department_id in #{id}
    or exists(select 1 from org_department_closure dc where dc.tenant_id=p.tenant_id and dc.descendant_department_id=p.owner_department_id and dc.ancestor_department_id in #{id})
    or p.owner_group_id in #{id})
  and p.principal_id not in #{id}
  and (p.owner_department_id is null or p.owner_department_id not in #{id})
  and not exists(select 1 from org_department_closure dd where dd.tenant_id=p.tenant_id and dd.descendant_department_id=p.owner_department_id and dd.ancestor_department_id in #{id})
  and (p.owner_group_id is null or p.owner_group_id not in #{id})
  and not exists(select 1 from resource_scope_denies d where d.tenant_id=p.tenant_id and d.resource_type='ISSUE_PRINCIPAL' and d.deny_state='ACTIVE' and d.valid_from<=now() and (d.valid_to is null or d.valid_to>now()) and d.principal_type=#{scope.principalType} and d.principal_id=#{scope.principalId} and (d.permission_code is null or d.permission_code=#{scope.permissionCode}) and (d.scope_type='TENANT' or (d.scope_type='RESOURCE' and d.scope_ref_id=p.principal_id) or (d.scope_type in ('OWNER','DEPARTMENT') and d.scope_ref_id=p.owner_department_id) or (d.scope_type='GROUP' and d.scope_ref_id=p.owner_group_id) or (d.scope_type='DEPARTMENT_SUBTREE' and exists(select 1 from org_department_closure x where x.tenant_id=p.tenant_id and x.ancestor_department_id=d.scope_ref_id and x.descendant_department_id=p.owner_department_id))))
order by p.principal_name,p.principal_id limit #{limit}

select c.* from integration_credentials c join integration_principals p on p.tenant_id=c.tenant_id and p.principal_id=c.principal_id
where c.tenant_id=#{tenantId} and c.principal_id=#{principalId}
  and #{scope.denyAll}=false and (#{scope.tenantWide}=true
    or c.credential_id in #{id}
    or p.owner_department_id in #{id}
    or exists(select 1 from org_department_closure dc where dc.tenant_id=p.tenant_id and dc.descendant_department_id=p.owner_department_id and dc.ancestor_department_id in #{id})
    or p.owner_group_id in #{id})
  and c.credential_id not in #{id}
  and not exists(select 1 from resource_scope_denies d where d.tenant_id=c.tenant_id and d.resource_type='ISSUE_CREDENTIAL_METADATA' and d.deny_state='ACTIVE' and d.valid_from<=now() and (d.valid_to is null or d.valid_to>now()) and d.principal_type=#{scope.principalType} and d.principal_id=#{scope.principalId} and (d.permission_code is null or d.permission_code=#{scope.permissionCode}) and (d.scope_type='TENANT' or (d.scope_type='RESOURCE' and d.scope_ref_id=c.credential_id) or (d.scope_type in ('OWNER','DEPARTMENT') and d.scope_ref_id=p.owner_department_id) or (d.scope_type='GROUP' and d.scope_ref_id=p.owner_group_id) or (d.scope_type='DEPARTMENT_SUBTREE' and exists(select 1 from org_department_closure x where x.tenant_id=p.tenant_id and x.ancestor_department_id=d.scope_ref_id and x.descendant_department_id=p.owner_department_id))))
order by c.created_at desc,c.credential_id limit #{limit}

select m.* from integration_project_mappings m
where m.tenant_id=#{tenantId} and m.connection_id=#{connectionId}
  and #{scope.denyAll}=false and (#{scope.tenantWide}=true
    or m.mapping_id in #{id}
    or m.department_id in #{id}
    or exists(select 1 from org_department_closure dc where dc.tenant_id=m.tenant_id and dc.descendant_department_id=m.department_id and dc.ancestor_department_id in #{id})
    or m.group_id in #{id})
  and m.mapping_id not in #{id}
  and (m.department_id is null or m.department_id not in #{id})
  and not exists(select 1 from org_department_closure dd where dd.tenant_id=m.tenant_id and dd.descendant_department_id=m.department_id and dd.ancestor_department_id in #{id})
  and (m.group_id is null or m.group_id not in #{id})
  and not exists(select 1 from resource_scope_denies d where d.tenant_id=m.tenant_id and d.resource_type='ISSUE_PROJECT_MAPPING' and d.deny_state='ACTIVE' and d.valid_from<=now() and (d.valid_to is null or d.valid_to>now()) and d.principal_type=#{scope.principalType} and d.principal_id=#{scope.principalId} and (d.permission_code is null or d.permission_code=#{scope.permissionCode}) and (d.scope_type='TENANT' or (d.scope_type='RESOURCE' and d.scope_ref_id=m.mapping_id) or (d.scope_type in ('OWNER','DEPARTMENT') and d.scope_ref_id=m.department_id) or (d.scope_type='GROUP' and d.scope_ref_id=m.group_id) or (d.scope_type='DEPARTMENT_SUBTREE' and exists(select 1 from org_department_closure x where x.tenant_id=m.tenant_id and x.ancestor_department_id=d.scope_ref_id and x.descendant_department_id=m.department_id))))
order by m.resolution_priority,m.mapping_id limit #{limit}
